import bisect
i = bisect.bisect_left(a, x)    # first index with a[i] >= x  (lower_bound)
j = bisect.bisect_right(a, x)   # first index with a[j] >  x  (upper_bound)
found = i < len(a) and a[i] == x

# Hand-rolled, for when you need the index semantics explicit.
def search(a: list[int], target: int) -> int:
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2        # Python ints are arbitrary precision — no overflow
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

# Binary search on the answer: smallest value for which feasible() is True.
# The predicate must be monotonic: False...False, True...True.
def min_feasible(lo: int, hi: int) -> int:
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid                # keep mid as a candidate
        else:
            lo = mid + 1
    return lo

