# The pattern behind next-greater, largest-rectangle, stock-span and
# daily-temperatures. Each index is pushed and popped once, so O(n).
def next_greater(a: list[int]) -> list[int]:
    res = [-1] * len(a)
    stack: list[int] = []              # indices, values decreasing
    for i, x in enumerate(a):
        while stack and a[stack[-1]] < x:
            res[stack.pop()] = x
        stack.append(i)
    return res

# Sliding window maximum with a deque. Use deque, not list — list.pop(0) is O(n).
from collections import deque

def window_max(a: list[int], k: int) -> list[int]:
    dq: deque[int] = deque()           # indices
    out: list[int] = []
    for i, x in enumerate(a):
        while dq and dq[0] <= i - k:
            dq.popleft()               # fell out of the window
        while dq and a[dq[-1]] <= x:
            dq.pop()                   # dominated by x, can never be the max
        dq.append(i)
        if i >= k - 1:
            out.append(a[dq[0]])
    return out

