from collections import defaultdict, deque

adj = defaultdict(list)
adj[u].append(v)

# BFS gives shortest path in an UNWEIGHTED graph. Mark visited on enqueue,
# not on dequeue, or a node gets queued many times.
def bfs(src: int, n: int) -> list[int]:
    dist = [-1] * n
    dist[src] = 0
    q = deque([src])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

# Grid BFS — the same thing with implicit neighbours.
DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))

# Kahn's topological sort. Fewer than n nodes out means there is a cycle.
def topo_sort(n: int) -> list[int]:
    indeg = [0] * n
    for u in range(n):
        for v in adj[u]:
            indeg[v] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    order: list[int] = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return order if len(order) == n else []      # [] => cycle

# Dijkstra with a heap, for non-negative weights.
import heapq

def dijkstra(src: int, n: int) -> list[float]:
    dist = [float('inf')] * n
    dist[src] = 0
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue                              # stale entry
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    return dist

