from functools import cache

# 1. Top-down. @cache turns naive recursion into memoised DP for free —
#    the fastest way to get a correct baseline in an interview.
@cache
def rob(i: int) -> int:
    if i >= len(nums):
        return 0
    return max(nums[i] + rob(i + 2), rob(i + 1))

# 2. Bottom-up table.
def rob_tab(nums: list[int]) -> int:
    n = len(nums)
    dp = [0] * (n + 2)
    for i in range(n - 1, -1, -1):
        dp[i] = max(nums[i] + dp[i + 2], dp[i + 1])
    return dp[0]

# 3. Rolling — only two states are ever read.
def rob_rolling(nums: list[int]) -> int:
    take = skip = 0
    for x in reversed(nums):
        take, skip = max(x + skip, take), take
    return take

# 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used at most once;
# going upward silently turns it into the unbounded version.
def knapsack(wt: list[int], val: list[int], cap: int) -> int:
    dp = [0] * (cap + 1)
    for w_i, v_i in zip(wt, val):
        for w in range(cap, w_i - 1, -1):
            dp[w] = max(dp[w], v_i + dp[w - w_i])
    return dp[cap]

# LCS — the template for most string DP.
def lcs(a: str, b: str) -> int:
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            dp[i][j] = dp[i - 1][j - 1] + 1 if a[i - 1] == b[j - 1] \
                       else max(dp[i - 1][j], dp[i][j - 1])
    return dp[len(a)][len(b)]

